export type Eve03CanonicalCatalog = typeof EVE_03_CANONICAL_CATALOG;
export type SourceNodeRecord = Eve03CanonicalCatalog["modules"]["source_node_registry"][number];
export type SourceCodeRecord = Eve03CanonicalCatalog["modules"]["source_code_registry"][number];
export type CanonicalVariableRecord = Eve03CanonicalCatalog["modules"]["canonical_variables"][number];
export type CriticalRouteRecord = Eve03CanonicalCatalog["modules"]["critical_routes"][number];
export type NodeEpistemicPolicy = Eve03CanonicalCatalog["modules"]["epistemic_policy"]["node_policies"][number];

const nodeIndex = new Map<string, SourceNodeRecord>(
  EVE_03_CANONICAL_CATALOG.modules.source_node_registry.map((row) => [row.source_node_ref_id, row]),
);

const codeIndex = new Map<string, SourceCodeRecord>(
  EVE_03_CANONICAL_CATALOG.modules.source_code_registry.map((row) => [
    `${row.source_block}::${row.source_question_code_intact}`,
    row,
  ]),
);

const variableIndex = new Map<string, CanonicalVariableRecord>(
  EVE_03_CANONICAL_CATALOG.modules.canonical_variables.map((row) => [row.variable_name, row]),
);

const routeIndex = new Map<string, CriticalRouteRecord>(
  EVE_03_CANONICAL_CATALOG.modules.critical_routes.map((row) => [row.critical_route_id, row]),
);

export function getSourceNode(sourceNodeRefId: string): SourceNodeRecord | undefined {
  return nodeIndex.get(sourceNodeRefId);
}

export function getSourceCode(sourceBlock: string, intactCode: string): SourceCodeRecord | undefined {
  return codeIndex.get(`${sourceBlock}::${intactCode}`);
}

export function getCanonicalVariable(variableName: string): CanonicalVariableRecord | undefined {
  return variableIndex.get(variableName);
}

export function getCriticalRoute(criticalRouteId: string): CriticalRouteRecord | undefined {
  return routeIndex.get(criticalRouteId);
}

export function getNodeEpistemicPolicy(sourceNodeRefId: string): NodeEpistemicPolicy | undefined {
  return EVE_03_CANONICAL_CATALOG.modules.epistemic_policy.node_policies.find(
    (row) => row.capture_node_id === sourceNodeRefId,
  );
}

export function listPendingVariableDefinitions(): readonly CanonicalVariableRecord[] {
  return EVE_03_CANONICAL_CATALOG.modules.canonical_variables.filter(
    (row) => row.registry_status === "referenced_not_defined_in_variables_source",
  );
}

export function listNodesByBlock(sourceBlock: string): readonly SourceNodeRecord[] {
  return EVE_03_CANONICAL_CATALOG.modules.source_node_registry.filter(
    (row) => row.source_block === sourceBlock,
  );
}

export function assertCanonicalCatalogRuntimeBoundary(): void {
  if (EVE_03_CANONICAL_CATALOG.qa.final_diagnosis_enabled) {
    throw new Error("EVE03_BOUNDARY_VIOLATION: final diagnosis must remain disabled.");
  }
  if (EVE_03_CANONICAL_CATALOG.qa.vsm_diagnosis_enabled) {
    throw new Error("EVE03_BOUNDARY_VIOLATION: VSM diagnosis must remain disabled.");
  }
  if (!EVE_03_CANONICAL_CATALOG.qa.genealogy_complete) {
    throw new Error("EVE03_GENEALOGY_INCOMPLETE");
  }
}
